INSERT INTO chains VALUES(2,0,'[{"citation":"the source''s own parallax","native":"$native","step":"published_parallax"},{"citation":"d = 1 / ϖ, a fair estimate where σ_ϖ / ϖ is small (Bailer-Jones 2015, PASP 127, 994)","parallax_mas":"$1","step":"inverted_parallax"},{"citation":"Hogg 1999, arXiv:astro-ph/9905116, eq. 21: D_L / D_C − 1 = z ≈ H0 d / c","largest_difference":"$2","step":"euclidean"},{"citation":"x toward α = 0, z toward the north pole, origin at the barycentre","step":"cartesian"},{"citation":"ESA 1997, The Hipparcos Catalogue, vol. 1, §1.5.3","step":"rotated","to":"galactic"},{"citation":"Lahav et al. 2000, MNRAS 312, 166","step":"rotated","to":"supergalactic"}]',2,1);
INSERT INTO chains VALUES(2,1,'[{"citation":"the source''s own value","measure":"luminosity","native":"$native","step":"published"},{"citation":"the distance modulus, μ = 5 log10(d / 10 pc)","modulus":"$native","step":"from_modulus"},{"citation":"the source''s own value","measure":"luminosity","reason":"the entry has no CMB-frame redshift to convert it with: it stays a luminosity distance, larger than the comoving one by the factor 1 + z","step":"kept_as_published"},{"citation":"Mignard & Froeschlé 2000, A&A 354, 732","from":"fk5_j2000","step":"to_icrs"},{"citation":"x toward α = 0, z toward the north pole, origin at the barycentre","step":"cartesian"},{"citation":"ESA 1997, The Hipparcos Catalogue, vol. 1, §1.5.3","step":"rotated","to":"galactic"},{"citation":"Lahav et al. 2000, MNRAS 312, 166","step":"rotated","to":"supergalactic"}]',0,4);
INSERT INTO chains VALUES(2,2,'[{"citation":"the source''s own value","measure":"unspecified","native":"$native","step":"published"},{"citation":"the source''s own value","measure":"unspecified","reason":"its source does not say which distance it publishes","step":"kept_as_published"},{"citation":"Mignard & Froeschlé 2000, A&A 354, 732","from":"fk5_j2000","step":"to_icrs"},{"citation":"x toward α = 0, z toward the north pole, origin at the barycentre","step":"cartesian"},{"citation":"ESA 1997, The Hipparcos Catalogue, vol. 1, §1.5.3","step":"rotated","to":"galactic"},{"citation":"Lahav et al. 2000, MNRAS 312, 166","step":"rotated","to":"supergalactic"}]',0,4);
INSERT INTO chains VALUES(2,3,'[{"citation":"Hogg 1999, arXiv:astro-ph/9905116, eq. 15, flat ΛCDM","cmb_redshift":"$1","dipole":"planck2018","heliocentric_redshift":"$2","step":"comoving_from_redshift"},{"citation":"Mignard & Froeschlé 2000, A&A 354, 732","from":"fk5_j2000","step":"to_icrs"},{"citation":"x toward α = 0, z toward the north pole, origin at the barycentre","step":"cartesian"},{"citation":"ESA 1997, The Hipparcos Catalogue, vol. 1, §1.5.3","step":"rotated","to":"galactic"},{"citation":"Lahav et al. 2000, MNRAS 312, 166","step":"rotated","to":"supergalactic"}]',2,2);
INSERT INTO chains VALUES(2,4,'[{"citation":"Hogg 1999, arXiv:astro-ph/9905116, eq. 15, flat ΛCDM","cmb_redshift":"$1","step":"comoving_from_published_cmb_redshift"},{"citation":"Mignard & Froeschlé 2000, A&A 354, 732","from":"fk5_j2000","step":"to_icrs"},{"citation":"x toward α = 0, z toward the north pole, origin at the barycentre","step":"cartesian"},{"citation":"ESA 1997, The Hipparcos Catalogue, vol. 1, §1.5.3","step":"rotated","to":"galactic"},{"citation":"Lahav et al. 2000, MNRAS 312, 166","step":"rotated","to":"supergalactic"}]',1,4);
